---@param oldCardGuid string | nil
function LadderCompetionMainTeamNode:UpdateNodeState_(oldCardGuid)
    local isEmptyCard = self:IsEmptyCard()
    CfUtils.SetActive(self.EmptyGroup, isEmptyCard)
    CfUtils.SetActive(self.CardPar, not isEmptyCard)

    if not isEmptyCard then
        local cardDojo = cardComponent:GetCardById(self:GetTeamDojo().refId)
        self:UpdateCardView_(cardDojo)
    end

    if tostring(oldCardGuid) == tostring(self:GetTeamDojo().refId) then
        CfUtils.PlayAnimation(self.AnimRoot, 'LadderCompetionMainTeam_Default')
    else
        CfUtils.PlayAnimation(self.AnimRoot, isEmptyCard and 'LadderCompetionMainTeam_Default' or 'LadderCompetionMainTeam_Swtich')
    end
end

---@param cardDojo CardDojo
function LadderCompetionMainTeamNode:UpdateCardView_(cardDojo)
    self.cardHeadNodeEnv_:FreshNode(cardDojo, true, 0, true)

    if checkNumber(self.teamDojo_.fettersCardId) ~= 0 then
        KTool.SetActive(self.FetterHead, true)
        local fetterCardDojo = cardComponent:GetCardById(self:GetTeamDojo().fettersId)
        if fetterCardDojo then
            local fetterCardVo = cardConfMgr:GetCardByRefId(self:GetTeamDojo().fettersCardId)
            local fetterSkinId = checkInt(fetterCardDojo.cardSkin)
            local fetterSkinVo = cardConfMgr:GetCardSkinBySkinId(fetterSkinId)
            CfUtils.FillImage(self.FetterHeadImg, fetterSkinVo.buffHead)
            CfUtils.SetUISwitchImage(self.FetterQualityImg, fetterCardDojo:GetRare())
        else
            KTool.SetActive(self.FetterHead, false)
        end
    else
        KTool.SetActive(self.FetterHead, false)
    end
end

---@param finishCB fun():void
function LadderCompetionMainTeamNode:DoNodeHomingAction_(finishCB)
    if self.nodeActionCo_ ~= nil then
        cs_coroutine.stop(self.nodeActionCo_)
    end
    self.nodeActionCo_ = cs_coroutine.start(function()

        --- append blocker
        UIRaycastBlocker:AddCondition(NODE_ACTION_BLOCKER_NAME)

        -- tween move
        local actionTime = 0.15
        self.controller.transform:DOLocalMove(self.defaultPosition_, actionTime)
        coroutine.yield(CS.UnityEngine.WaitForSeconds(actionTime))

        -- reset pos & order
        self:UpdateNodPosition_()
        self:UpdateNodOrderIndex_()

        -- remove blocker
        UIRaycastBlocker:RemoveCondition(NODE_ACTION_BLOCKER_NAME)

        -- finish callback
        if finishCB then
            finishCB()
        end

        self.nodeActionCo_ = nil
    end)
end

---@param swapNode LadderCompetionMainTeamNode
---@param finishCB fun():void
function LadderCompetionMainTeamNode:DoNodeSwappingAction_(swapNode, finishCB)
    if self.nodeActionCo_ ~= nil then
        cs_coroutine.stop(self.nodeActionCo_)
    end
    self.nodeActionCo_ = cs_coroutine.start(function()

        --- append blocker
        UIRaycastBlocker:AddCondition(NODE_ACTION_BLOCKER_NAME)

        local GetBezierPath = function(startPos, endPos)
            local isFromDown = self.controller.transform.localPosition.y < startPos.y
            local controlPos = Vector3(
                    startPos.x + (endPos.x - startPos.x) / 2,
                    startPos.y + (isFromDown and 1 or -1) * 200,
                    0
            )
            return { startPos, controlPos, endPos }
        end

        -- tween move
        local actionTime = 0.2
        local tweenSequence = DOTween.Sequence()
        tweenSequence:Append(self.controller.transform:DOLocalMove(swapNode.defaultPosition_, actionTime))
        -- tweenSequence:Join(swapNode.controller.transform:DOLocalMove(self.defaultPosition_, actionTime))
        tweenSequence:Join(swapNode.controller.transform:DOLocalPath(GetBezierPath(
                swapNode.controller.transform.localPosition,
                self.defaultPosition_
        ), actionTime))
        tweenSequence:PlayForward()
        coroutine.yield(CS.UnityEngine.WaitForSeconds(actionTime))

        -- swap both node
        local oldDefaultPosition = self.defaultPosition_
        local oldInitSiblingIndex = self.initSiblingIndex_
        self.defaultPosition_ = swapNode.defaultPosition_
        self.initSiblingIndex_ = swapNode.initSiblingIndex_
        swapNode.defaultPosition_ = oldDefaultPosition
        swapNode.initSiblingIndex_ = oldInitSiblingIndex

        -- reset both pos & order
        self:UpdateNodPosition_()
        self:UpdateNodOrderIndex_()
        swapNode:UpdateNodPosition_()
        swapNode:UpdateNodOrderIndex_()

        -- remove blocker
        UIRaycastBlocker:RemoveCondition(NODE_ACTION_BLOCKER_NAME)

        -- finish callback
        if finishCB then
            finishCB()
        end

        self.nodeActionCo_ = nil
    end)
end


