---@param eventData UnityEngine.EventSystems.PointerEventData
function LadderCompetionMainTeamNode:OnNodeDragBeginHandler_(eventData)
    if isNull(eventData) or self:IsEmptyCard() then
        return
    end

    local topSiblingIndex = self.parentTransform_.childCount
    self:UpdateNodOrderIndex_(topSiblingIndex)

    local nodeRtComp = self.parentRtComponent_
    local screenPos = eventData.position
    local uiCamera = URPCameraController.uiCamera
    local _, nowVec2 = RectTransformUtility.ScreenPointToLocalPointInRectangle(nodeRtComp, screenPos, uiCamera)
    self.dragOffsetVector2_.x = self.controller.transform.localPosition.x - nowVec2.x
    self.dragOffsetVector2_.y = self.controller.transform.localPosition.y - nowVec2.y
    self.isPointerDragging_ = true
end

---@param eventData UnityEngine.EventSystems.PointerEventData
function LadderCompetionMainTeamNode:OnNodeDragMovedHandler_(eventData)
    if isNull(eventData) or self:IsEmptyCard() then
        return
    end
    if not self.isPointerDragging_ then
        return
    end

    local nodeRtComp = self.parentRtComponent_
    local screenPos = eventData.position
    local uiCamera = URPCameraController.uiCamera
    local _, nowVec2 = RectTransformUtility.ScreenPointToLocalPointInRectangle(nodeRtComp, screenPos, uiCamera)
    self:UpdateNodPosition_(Vector3(nowVec2.x + self.dragOffsetVector2_.x, nowVec2.y + self.dragOffsetVector2_.y, 0))
end

---@param eventData UnityEngine.EventSystems.PointerEventData
function LadderCompetionMainTeamNode:OnNodeDragEndedHandler_(eventData)
    if isNull(eventData) or self:IsEmptyCard() then
        return
    end
    if not self.isPointerDragging_ then
        return
    end

    ---@type LadderCompetionMainTeamNode
    local collisionNode = nil

    -- check nodes collision
    local nodePosition = self.controller.transform.position
    local nodeScreenPos = Vector2(nodePosition.x, nodePosition.y)
    for _, otherNode in ipairs(self:GetAllNodeList()) do
        if otherNode ~= self and otherNode:IsEmptyCard() == false then
            local otherRtComp = otherNode.controller.transform:GetComponent(typeof(RectTransform))
            local isContains = RectTransformUtility.RectangleContainsScreenPoint(otherRtComp, nodeScreenPos)
            if isContains then
                collisionNode = otherNode
                break
            end
        end
    end

    if collisionNode then
        -- swap both node
        self:DoNodeSwappingAction_(collisionNode, function()
            if self:GetDragToTargetCb() then
                self:GetDragToTargetCb()(self, collisionNode)
            end
        end)
    else
        -- reset node
        self:DoNodeHomingAction_()
    end

    self.isPointerDragging_ = false
end

